package mz.bam.seeky.android;
import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.Drawable;import android.graphics.pdf.PdfRenderer;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.text.*;import java.io.*;import java.net.URLDecoder;import java.util.*;import java.util.zip.*;import org.w3c.dom.*;
/** Bounded first-page/declared-cover extraction. It never installs an APK or modifies a source. */
final class ThumbnailSource {
 static final int EDGE=320;static final long COPY_LIMIT=16777216;
 static Bitmap image(InputStream in)throws IOException{byte[] bytes=read(in,2097152);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth<1||o.outHeight<1)return null;o.inJustDecodeBounds=false;o.inSampleSize=ImageBudget.sample(o.outWidth,o.outHeight,EDGE);return BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);}
 static byte[] read(InputStream in,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(out.size()+n>max)throw new IOException("Preview limit");out.write(b,0,n);}return out.toByteArray();}
 static byte[] entry(ZipFile zip,String path,int max)throws IOException{ZipEntry e=zip.getEntry(BookArchive.safePath(path));if(e==null||e.isDirectory()||e.getSize()>max)return null;try(InputStream in=zip.getInputStream(e)){return read(in,max);}}
 static Bitmap decode(byte[] bytes){if(bytes==null)return null;BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth<1||o.outHeight<1)return null;o.inJustDecodeBounds=false;o.inSampleSize=ImageBudget.sample(o.outWidth,o.outHeight,EDGE);return BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);}
 static Bitmap load(Context context,Catalog.Entry e)throws Exception{File custom=BookCovers.custom(context,e);if(custom!=null){BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(custom.getPath(),options);options.inSampleSize=ImageBudget.sample(options.outWidth,options.outHeight,EDGE);options.inJustDecodeBounds=false;return BitmapFactory.decodeFile(custom.getPath(),options);}Uri uri=Uri.parse(e.uri);String kind=MediaFormats.kind(e.name,e.mime);
  if(kind.equals("image")){BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=context.getContentResolver().openInputStream(uri)){if(in==null)return null;BitmapFactory.decodeStream(in,null,o);}if(o.outWidth<1||o.outHeight<1)return null;o.inJustDecodeBounds=false;o.inSampleSize=ImageBudget.sample(o.outWidth,o.outHeight,EDGE);try(InputStream in=context.getContentResolver().openInputStream(uri)){return BitmapFactory.decodeStream(in,null,o);}}
  if(kind.equals("pdf")){try(ParcelFileDescriptor descriptor=context.getContentResolver().openFileDescriptor(uri,"r")){if(descriptor==null)return null;try(PdfRenderer pdf=new PdfRenderer(descriptor)){if(pdf.getPageCount()==0)return null;try(PdfRenderer.Page page=pdf.openPage(0)){int[] size=ImageBudget.fit(page.getWidth(),page.getHeight(),EDGE,76800);Bitmap b=Bitmap.createBitmap(size[0],size[1],Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);page.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);return b;}}}}
  File local=null,temp=null;try{if("file".equals(uri.getScheme()))local=new File(uri.getPath());else{if(e.size>COPY_LIMIT)return null;temp=File.createTempFile("seeky-preview-",".tmp",context.getCacheDir());temp.delete();try(InputStream in=context.getContentResolver().openInputStream(uri)){if(in==null)return null;StudyFiles.copy(in,temp,COPY_LIMIT,()->Thread.currentThread().isInterrupted());}local=temp;}
   if(MediaFormats.ext(e.name).equals("apk")){PackageManager pm=context.getPackageManager();PackageInfo info=pm.getPackageArchiveInfo(local.getPath(),0);if(info==null||info.applicationInfo==null)return null;ApplicationInfo app=info.applicationInfo;app.sourceDir=local.getPath();app.publicSourceDir=local.getPath();Drawable icon=app.loadIcon(pm);Bitmap bitmap=Bitmap.createBitmap(80,80,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);icon.setBounds(0,0,80,80);icon.draw(canvas);return bitmap;}
   if(kind.equals("epub"))try(ZipFile zip=new ZipFile(local)){if(zip.size()>12000)return null;byte[] container=entry(zip,"META-INF/container.xml",262144);if(container==null)return null;NodeList roots=BookArchive.xml(container).getElementsByTagNameNS("*","rootfile");if(roots.getLength()==0)return null;String opf=BookArchive.safePath(((Element)roots.item(0)).getAttribute("full-path"));byte[] packageBytes=entry(zip,opf,262144);if(packageBytes==null)return null;Document doc=BookArchive.xml(packageBytes);String cover="";NodeList meta=doc.getElementsByTagNameNS("*","meta");for(int i=0;i<meta.getLength();i++){Element m=(Element)meta.item(i);if(m.getAttribute("name").equals("cover"))cover=m.getAttribute("content");}NodeList items=doc.getElementsByTagNameNS("*","item");for(int i=0;i<items.getLength();i++){Element item=(Element)items.item(i);if(item.getAttribute("properties").contains("cover-image")||!cover.isEmpty()&&item.getAttribute("id").equals(cover)){String href=URLDecoder.decode(item.getAttribute("href").replace("+","%2B"),"UTF-8");String base=opf.contains("/")?opf.substring(0,opf.lastIndexOf('/')+1):"";return decode(entry(zip,base+href,2097152));}}return null;}
   if(kind.equals("docx")){try(ZipFile zip=new ZipFile(local)){if(zip.size()>12000)return null;for(String name:new String[]{"docProps/thumbnail.jpeg","docProps/thumbnail.jpg","docProps/thumbnail.png"}){Bitmap b=decode(entry(zip,name,2097152));if(b!=null)return b;}ZipEntry document=zip.getEntry("word/document.xml");if(document==null||document.getSize()>262144)return null;}try(BookArchive book=new BookArchive(local,false)){String value=book.chapter(0);Bitmap b=Bitmap.createBitmap(240,320,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(Color.WHITE);TextPaint paint=new TextPaint(Paint.ANTI_ALIAS_FLAG);paint.setColor(0xff1d4f91);paint.setTextSize(18);paint.setTypeface(Typeface.DEFAULT_BOLD);c.drawText("W",16,30,paint);paint.setTextSize(11);paint.setTypeface(Typeface.DEFAULT);paint.setColor(0xff394454);StaticLayout layout=StaticLayout.Builder.obtain(value,0,Math.min(1400,value.length()),paint,208).setMaxLines(19).setEllipsize(TextUtils.TruncateAt.END).build();c.save();c.translate(16,48);layout.draw(c);c.restore();return b;}}
   return null;
  }finally{if(temp!=null){temp.delete();new File(temp+".part").delete();}}
 }
}
